/* <slot>/images.tsx: GENERATED from images.json + the skin library, never edited by hand.
 *
 *   /* images.tsx: generated by `node cli.mjs images` from images.json; never edit *\/
 *   const TOOL_IMAGES: Record<string, string> = {
 *     "piece": "data:image/webp;base64,....",
 *   };
 *   const TOOL_THEME: any = {"key":[...],"enter":[...],"soft":[...],"panel":[...],"slot":"#..."};   (when a theme resolved)
 *
 * One entry per line, so a line-wise reader never needs to parse the data. The runtime's <Skin name=...> reads
 * TOOL_IMAGES; a key that is missing (rejected, not made yet) simply draws nothing and the tool's plain vector
 * shape shows. images.json gets each key's final size and bytes back.
 */
import fs from "node:fs";
import path from "node:path";
import { writeJsonAtomic } from "./library.mjs";

export const HEADER = "/* images.tsx: generated by `node cli.mjs images` from images.json; never edit */";

/* entries: [{ key, uri, w, h, bytes, uriBytes, hash, q, object, kind }] in images.json order;
   themed: { theme, from } (theme.mjs resolveTheme, already validated) or null. The keypad THEME follows the picture:
   one line, JSON, right after TOOL_IMAGES; nothing at all when there is none (the runtime's own pale keys).
   (make.mjs passes null for a slot whose pinned runtime has no THEME, caps.theme: nothing would read it.) */
export function emitSlot(dir, plan, entries, themed = null) {
  const lines = [HEADER, "const TOOL_IMAGES: Record<string, string> = {"];
  for (const e of entries) lines.push(`  ${JSON.stringify(e.key)}: ${JSON.stringify(e.uri)},`);
  lines.push("};");
  if (themed) lines.push(`const TOOL_THEME: any = ${JSON.stringify(themed.theme)};`);
  lines.push("");
  const tsx = path.join(dir, "images.tsx");
  const text = lines.join("\n");
  fs.writeFileSync(tsx, text);
  const byKey = Object.fromEntries(entries.map((e) => [e.key, e]));
  const { themeMade, ...planRest } = plan;
  const next = { ...planRest, ...(themed ? { themeMade: { from: themed.from, ...themed.numbers } } : {}), images: (plan.images || []).map((img) => {
    const e = byKey[img.key];
    const { made, ...rest } = img;
    return e ? { ...rest, made: { w: e.w, h: e.h, bytes: e.bytes, uriBytes: e.uriBytes, q: e.q, skin: e.hash } } : rest;
  }) };
  writeJsonAtomic(path.join(dir, "images.json"), next);
  return { file: tsx, bytes: Buffer.byteLength(text), keys: entries.map((e) => e.key), theme: themed ? themed.from : null };
}

/* the TOOL_THEME an images.tsx carries now (null when none) */
export function readTheme(dir) {
  const f = path.join(dir, "images.tsx");
  if (!fs.existsSync(f)) return null;
  const m = /^const TOOL_THEME: any = (\{.*\});\s*$/m.exec(fs.readFileSync(f, "utf8"));
  try { return m ? JSON.parse(m[1]) : null; } catch { return null; }
}

/* the keys an images.tsx carries now, with their data-URI length (status reads this, never the base64 itself) */
export function readEmitted(dir) {
  const f = path.join(dir, "images.tsx");
  if (!fs.existsSync(f)) return null;
  const out = {};
  for (const line of fs.readFileSync(f, "utf8").split(/\r?\n/)) {
    const m = /^\s*"([a-z0-9_]+)":\s*"(data:[^"]*)",?\s*$/.exec(line);
    if (m) out[m[1]] = m[2].length;
  }
  return out;
}
